mapper.delete:
DELETE FROM group_chat_agent_decision decision
USING group_chat_reply_step step, group_chat_turn turn_row
WHERE decision.reply_step_id = step.id
  AND step.turn_id = turn_row.id
  AND turn_row.conversation_id = #{conversationId}
  AND decision.id > #{maxId}

DELETE FROM group_chat_tool_call tool_call
USING group_chat_reply_step step, group_chat_turn turn_row
WHERE tool_call.reply_step_id = step.id
  AND step.turn_id = turn_row.id
  AND turn_row.conversation_id = #{conversationId}
  AND tool_call.id > #{maxId}

DELETE FROM group_chat_message
WHERE conversation_id = #{conversationId}
  AND id > #{maxId}

DELETE FROM group_chat_reply_step step
USING group_chat_turn turn_row
WHERE step.turn_id = turn_row.id
  AND turn_row.conversation_id = #{conversationId}
  AND step.id > #{maxId}

DELETE FROM group_chat_turn
WHERE conversation_id = #{conversationId}
  AND id > #{maxId}

DELETE FROM group_context_summary
WHERE conversation_id = #{conversationId}
  AND id > #{maxId}

DELETE FROM group_chat_topic
WHERE conversation_id = #{conversationId}
  AND id > #{maxId}

DELETE FROM dice_roll_result result
USING dice_roll_summary summary
WHERE result.summary_id = summary.id
  AND summary.conversation_id = #{conversationId}
  AND (summary.id > #{maxSummaryId}
       OR result.id > #{maxResultId})

DELETE FROM dice_roll_summary
WHERE conversation_id = #{conversationId}
  AND id > #{maxId}
